DO $$
DECLARE
   r RECORD;
   current_status VARCHAR;
   current_editor_id INT;
BEGIN
    FOR r IN SELECT * FROM moderation_events ORDER BY event_id LOOP
        SELECT status, editor_id INTO current_status, current_editor_id
        FROM articles
        WHERE article_id = r. article_id;

        IF r.action_type = 1 AND current_editor_id IS NULL AND current_status= 'pending' THEN
            UPDATE articles
            SET editor_id = r.editor_id
            WHERE article_id = r. article_id;

        ELSIF r.action_type = 2 AND current_editor_id = r.editor_id AND current_status = 'pending' THEN
            UPDATE articles
            SET status = 'published'
            WHERE article_id = r. article_id;

        ELSIF r.action_type = 3 AND current_editor_id = r.editor_id AND current_status = 'pending' THEN
            UPDATE articles
            SET status = 'draft', editor_id = NULL
            WHERE article_id = r. article_id;

        END IF;
    END LOOP;
END $$;





SELECT * FROM articles ORDER BY article_id;
